options.state:
{% set active = is_state('input_boolean.vaatwasser_sessie_bezig', 'on') %}
{%- if not active -%}
Geen sessie
{%- else -%}
{%- set cur_grof = states('input_text.vaatwasser_huidige_curve_grof').split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set curves_grof = states('input_text.vaatwasser_sessie_curves_grof').split(';') | reject('in', ['', 'unknown','unavailable']) | list -%}
{%- set cur_fijn = states('input_text.vaatwasser_huidige_curve').split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set curves_fijn = states('input_text.vaatwasser_sessie_curves').split(';') | reject('in', ['', 'unknown','unavailable']) | list -%}
{%- set curve_durs = states('input_text.vaatwasser_curve_duren').split(',') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set curve_kwh = states('input_text.vaatwasser_curve_kwh').split(',') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set ts = state_attr('input_datetime.vaatwasser_sessie_start', 'timestamp') -%}
{%- set elapsed = ((now().timestamp() - ts) / 60) if ts is not none else 0 -%}
{%- set n_fine = curves_fijn | length -%}
{%- set n_coarse = curves_grof | length -%}
{%- if n_fine == 0 or (cur_fijn | length == 0 and cur_grof | length == 0) -%}
Nog geen match
{%- else -%}
{%- set coarse_offset = n_fine - n_coarse -%}
{%- set ns = namespace(best_score=none, best_i=0, second_score=none, second_i=none) -%}
{%- for i in range(n_fine) -%}
{%- set score = namespace(v=0, has_any=false) -%}
{%- if cur_fijn | length > 0 -%}
{%- set hist_fine = curves_fijn[i].split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set nA = [cur_fijn|length, hist_fine|length] | min -%}
{%- if nA > 0 -%}
{%- set fd = namespace(v=0) -%}
{%- for j in range(nA) -%}{%- set fd.v = fd.v + (cur_fijn[j]-hist_fine[j])|abs -%}{%- endfor -%}
{%- set score.v = score.v + fd.v -%}
{%- set score.has_any = true -%}
{%- endif -%}
{%- endif -%}
{%- if cur_grof | length > 0 and i >= coarse_offset -%}
{%- set hist_coarse = curves_grof[i - coarse_offset].split('|') | reject('in', ['', 'unknown','unavailable']) | map('float') | list -%}
{%- set nB = [cur_grof|length, hist_coarse|length] | min -%}
{%- if nB > 0 -%}
{%- set cd = namespace(v=0) -%}
{%- for j in range(nB) -%}{%- set cd.v = cd.v + (cur_grof[j]-hist_coarse[j])|abs -%}{%- endfor -%}
{%- set score.v = score.v + cd.v -%}
{%- set score.has_any = true -%}
{%- endif -%}
{%- endif -%}
{%- if score.has_any -%}
{%- if ns.best_score is none or score.v < ns.best_score -%}
{%- set ns.second_score = ns.best_score -%}
{%- set ns.second_i = ns.best_i -%}
{%- set ns.best_score = score.v -%}
{%- set ns.best_i = i -%}
{%- elif ns.second_score is none or score.v < ns.second_score -%}
{%- set ns.second_score = score.v -%}
{%- set ns.second_i = i -%}
{%- endif -%}
{%- endif -%}
{%- endfor -%}
{%- if ns.best_score is none -%}
Nog geen match
{%- else -%}
{%- set fallback = (ns.second_i is not none and elapsed > (curve_durs[ns.best_i] + 5)) -%}
{%- set idx = ns.second_i if fallback else ns.best_i -%}
{%- set d = curve_durs[idx] | round(0) | int -%}
{%- set k = (curve_kwh[idx] | round(2)) if idx < (curve_kwh | length) else none -%}
Sessie #{{ idx + 1 }} · ~{{ d }} min{% if k is not none %} · {{ k }} kWh{% endif %}{% if fallback %} (fallback){% endif %}
{%- endif -%}
{%- endif -%}
{%- endif -%}
